    milestone_thresholds = {
        int(total * 0.25): "25%",
        int(total * 0.50): "50%",
        int(total * 0.75): "75%",
    }

    for idx, frame in enumerate(frames):
        if self._cancelled:
            break

        # Broadcast progress
        if self._cb.broadcast:
            try:
                self._cb.broadcast(build_progress_event(
                    frame=idx + 1,
                    total_frames=total,
                    status="rendering",
                ))
            except Exception:
                pass

        # Render and validate this frame
